//! Exact five-bit canonical seed with one clean processed flag.
//! Descending anchors activate once; exceptional collisions are repaired on
//! the full257-bit (z,flag) space by disjoint structural constant swaps.
use super::{builder::B,mask::mcx_dirty};
use crate::circuit::QubitId;
pub type Word=[u64;5];
fn bit(x:Word,i:usize)->bool{(x[i/64]>>(i%64))&1!=0}
fn anchor(n:usize,k:usize)->Word{let mut x=[0;5];for i in 0..5{if k&(1<<i)!=0{let j=n-5+i;x[j/64]|=1<<(j%64);}}x}
pub fn xor_eq(b:&mut B,z:&[QubitId],k:Word,out:QubitId,dirty:&[QubitId]){
 for(i,&q)in z.iter().enumerate(){if !bit(k,i){b.x(q);}}
 mcx_dirty(b,z,out,dirty);
 for(i,&q)in z.iter().enumerate(){if !bit(k,i){b.x(q);}}
}
/// Affine conjugation gives one exact controlled constant transposition.
/// The branch control and all arbitrary borrowed lanes are returned.
pub fn const_swap(b:&mut B,z:&[QubitId],left:Word,right:Word,ctl:QubitId,dirty:&[QubitId]){
 assert!(z.len()<=257);
 let Some(pivot)=(0..z.len()).find(|&i|bit(left,i)!=bit(right,i))else{return;};
 for(i,&q)in z.iter().enumerate(){if bit(left,i){b.x(q);}}
 for(i,&q)in z.iter().enumerate(){if i!=pivot&&bit(left,i)!=bit(right,i){b.cx(z[pivot],q);}}
 let mut cs=vec![ctl];for(i,&q)in z.iter().enumerate(){if i!=pivot{b.x(q);cs.push(q);}}
 mcx_dirty(b,&cs,z[pivot],dirty);
 for(i,&q)in z.iter().enumerate(){if i!=pivot{b.x(q);}}
 for(i,&q)in z.iter().enumerate().rev(){if i!=pivot&&bit(left,i)!=bit(right,i){b.cx(z[pivot],q);}}
 for(i,&q)in z.iter().enumerate(){if bit(left,i){b.x(q);}}
}
/// Canonical(z,flag) -> canonical(z',flag'), globally reversible. No clean
/// arithmetic flag is assumed: y[1..=3] are restored arbitrary helpers.
pub fn descending_row(b:&mut B,z:&[QubitId],a:&[QubitId],y:&[QubitId],flag:QubitId,j:usize,c:u64){
 assert_eq!(z.len(),a.len()+1);assert!((1..=31).contains(&j));
 let aj=anchor(z.len(),j);xor_eq(b,z,aj,flag,a);
 const_swap(b,z,aj,[0;5],flag,a);
 super::canonical_short_seed_dirty::short_modadd_canonical(b,z,a,flag,y[4],y[1],y[2],y[3],c);
}
pub fn generic_seed(b:&mut B,z:&[QubitId],a:&[QubitId],y:&[QubitId],flag:QubitId,c:u64){
 for j in(1..=31).rev(){descending_row(b,z,a,y,flag,j,c);}
 b.x(flag);xor_eq(b,z,[0;5],flag,a);
}
/// Every source group's transpositions are pairwise disjoint, hence their
/// product is an involution. A single dirty-equality echo therefore gates
/// the entire group exactly, including arbitrary incoming y[0].
pub fn correct_seed_exceptions(b:&mut B,z:&[QubitId],a:&[QubitId],y:&[QubitId],flag:QubitId){
 assert_eq!(z.len(),256);assert_eq!(a.len(),255);assert_eq!(y.len(),251);
 let mut target=z.to_vec();target.push(flag);
 let mut pred_dirty=y[1..].to_vec();pred_dirty.extend_from_slice(&z[..3]);
 for &(source,swaps)in GROUPS{
  for _ in 0..2{
   xor_eq(b,a,source,y[0],&pred_dirty);
   for &(u,v)in swaps{const_swap(b,&target,u,v,y[0],a);}
  }
 }
}
/// Initial z=(k*2^251), flag0; output z=k*a modp, flag0, for ALL
/// 1<=a<=p/2 and k0..31. Sources and251 passenger lanes are unchanged.
pub fn seed(b:&mut B,z:&[QubitId],a:&[QubitId],y:&[QubitId],flag:QubitId){
 generic_seed(b,z,a,y,flag,super::modp_frogdrop::C);
 correct_seed_exceptions(b,z,a,y,flag);
}
pub fn product_consume_five_high_clean(b:&mut B,z:&mut Vec<QubitId>,a:&[QubitId],y:&[QubitId],flag:QubitId){
 assert_eq!(z.len(),256);assert_eq!(a.len(),255);assert_eq!(y.len(),251);
 seed(b,z,a,y,flag);
 for i in(0..251).rev(){super::field_consume_fifth::horner_round(b,z,a,y,i,flag);}
}
